/* eslint-disable max-len */

'use strict';

/**
* Method which return the default option.
*
* @private
* @name defaults
* @returns {Object} - out
*/
function defaults( ) {
	var out = {};

	// Boolean indicating whether to automatically re-render on a `change` event:
	out.autoRender = false;

	// Boolean indicating whether to automatically re-render on a `change` event:
	out.autoInitialization = false;

	// Default background color code
	out.backgroundColor = 'Bwhite';

	// Default foreground color code
	out.foregroundColor = 'Fblack';

	out.ticsLabelBckColor = 'Bwhite';

	// Default glyph code
	out.glyph = 'space';

	// Default horizontel tics glyph
	out.horizontalTicsGlyph = 'topTee';

	// Default horizontel tics glyph
	out.horizontalAxisGlyph = 'horizontal';

	out.axisIntersectionGlyph = 'crossIntersection';

	// Default plot area height
	out.plotAreaHeight = 15;

	// Default plot area height
	out.plotAreaWidth = 80;

	// Default vertical tics glyph
	out.verticalTicsGlyph = 'rightTee';

	// Default vertical tics glyph
	out.verticalAxisGlyph = 'vertical';

	// Label formate
	out.labelFormate = [ '%s', '%s', '%s', '%s' ];

	// Axis tics Labels
	out.xAxisTicsLabels = [];
	out.yAxisTicsLabels = [];
	out.zAxisTicsLabels = [];
	out.wAxisTicsLabels = [];

	out.axisTicsLabels = [ out.xAxisTicsLabels, out.yAxisTicsLabels, out.zAxisTicsLabels, out.wAxisTicsLabels ];

	out.xAxisPos = 0;
	out.yAxisPos = 0;
	out.zAxisPos = 0;
	out.wAxisPos = 0;

	out.xAxis = false;
	out.yAxis = false;
	out.zAxis = false;
	out.wAxis = false;

	out.xTicSpacing = 1;
	out.yTicSpacing = 1;
	out.zTicSpacing = 1;
	out.wTicSpacing = 1;
	out.ticsSpacing = [ out.xTicSpacing, out.yTicSpacing, out.zTicSpacing, out.zTicSpacing ];

	out.xTicsLabelSpace = 1;
	out.yTicsLabelSpace = 1;
	out.zTicsLabelSpace = 1;
	out.wTicsLabelSpace = 1;

	return out;
}

module.exports = defaults;
